import java.nio.file.*;import java.util.*;import co.sirius.format.pontof.controller.ler.PontoFLer;import co.sirius.format.pontof.controller.gravar.PontoFGravar;
public class NativeControl {public static void main(String[]a)throws Exception{var p=new PontoFLer(Path.of(a[0]).toFile()).execute();new PontoFGravar(Path.of(a[1]).toFile(),p).execute();var q=new PontoFLer(Path.of(a[1]).toFile()).execute();var x=ReviewedBinary.leaves(p);var y=ReviewedBinary.leaves(q);var d=ReviewedBinary.diff(x,y);System.out.println("NATIVE_FIELDS "+x.size()+" DIFF "+d.size());d.stream().limit(20).forEach(System.out::println);}}
